struct Key {unsigned name;std::uint32_t site;unsigned column;bool operator<(const Key&k)const{return std::tie(name,site,column)<std::tie(k.name,k.site,k.column);}bool operator==(const Key&k)const{return name==k.name&&site==k.site&&column==k.column;}};
using Keys=std::set<Key>;
struct Stencil{Key output;Keys inputs;};
Keys contexts(std::uint32_t x){return {{1,x,0},{5,x,0}};}
void unite(Keys&a,const Keys&b){a.insert(b.begin(),b.end());}
Keys slotkeys(std::uint32_t x,int slot=-1){Keys keys;for(unsigned p=0;p<2;++p)if(slot<0||p==unsigned(slot))for(unsigned name:{0U,2U,3U})keys.insert({name,x,p});return keys;}
std::set<std::uint32_t> owners(const View&v){std::set<std::uint32_t>s;for(auto c:v.c)s.insert(c.site);for(auto e:v.e)s.insert(e.owner);return s;}
std::vector<Stencil> stencils(const View&v){std::set<std::uint32_t> centers;for(auto x:owners(v))for(int i=-1;i<=1;++i)for(int j=-1;j<=1;++j)for(int k=-1;k<=1;++k)centers.insert(site(v.L,add(xyz(v.L,x),{i,j,k})));std::vector<Stencil>out;const auto p=phase(v.tick);for(auto x:centers){for(auto name:{1U,5U})out.push_back({{name,x,0},{{name,x,0}}});for(unsigned slot=0;slot<2;++slot)for(auto name:{3U,2U,0U}){Key key{name,x,slot};Keys support{key};if(p==0&&(name==3||name==0)){unite(support,slotkeys(x));support.insert({1,x,0});}else if(p>=1&&p<=6&&(name==3||name==2)){const auto m=match(v,x,(p-1)/2,(p-1)%2);unite(support,slotkeys(m.owner));unite(support,slotkeys(m.head));unite(support,contexts(m.owner));unite(support,contexts(m.head));support.insert({4,m.owner,m.axis});}else if(p>=7&&slot==(((p-7)/6)^v.eta)){const auto m=match(v,x,((p-7)%6)/2,(p-7)%2);unite(support,slotkeys(m.owner,int(slot)));unite(support,slotkeys(m.head,int(slot)));unite(support,contexts(m.owner));unite(support,contexts(m.head));support.insert({4,m.owner,m.axis});if(name==3)for(unsigned a=0;a<3;++a){support.insert({4,x,a});support.insert({4,shift(v.L,x,a,-1),a});}}out.push_back({key,std::move(support)});}for(unsigned axis=0;axis<3;++axis){Key key{4,x,axis};Keys support{key};if(p>=7){const auto m=match(v,x,((p-7)%6)/2,(p-7)%2);if(m.owner==x&&m.axis==axis){const auto slot=((p-7)/6)^v.eta;unite(support,slotkeys(m.owner,int(slot)));unite(support,slotkeys(m.head,int(slot)));unite(support,contexts(m.owner));unite(support,contexts(m.head));}}out.push_back({key,std::move(support)});}}std::sort(out.begin(),out.end(),[](const Stencil&a,const Stencil&b){return a.output<b.output;});return out;}
Keys active_keys(const View&v){Keys keys;for(auto c:v.c)unite(keys,slotkeys(c.site,c.slot));for(auto e:v.e)keys.insert({4,e.owner,e.axis});return keys;}
