std::string keys_repr(const std::vector<Key>&v){std::vector<std::string>s;for(auto k:v)s.push_back("('"+std::string(NAMES[k.name])+"', "+std::to_string(k.site)+", "+std::to_string(k.column)+")");return tup(s);}
