struct StepObservation{Graph graph;std::array<bool,4>flags{};Conflict conflict;std::vector<Key>contact;Q::Events merged;bool merged_valid=false;};
StepObservation observe_step(const Q::State&before,const Q::State&after,const Q::Events&events,const std::array<Control,2>&controls,const std::array<Control,2>&following,const Catalogue&cat){const auto a=view(before),b=view(after);need(b.tick==add_tick(a.tick)&&a.L==b.L&&a.origin==b.origin&&a.eta==b.eta,"advancing joint context");for(unsigned i=0;i<2;++i){const auto&c=controls[i];const auto&n=following[i];check_control(c);check_control(n);need(c.L==a.L&&c.origin==a.origin&&c.eta==a.eta&&c.tick==a.tick&&n.L==b.L&&n.origin==b.origin&&n.eta==b.eta&&n.tick==b.tick,"control/joint context");const auto expected=advance_control(c,cat);need(expected.node==n.node&&expected.plus==n.plus,"counterfactual successor");}const auto base=superpose(controls[0],controls[1],cat),next=superpose(following[0],following[1],cat);const auto pa=control_payload(controls[0],cat),pb=control_payload(controls[1],cat);const auto ka=active_keys(pa),kb=active_keys(pb);StepObservation out;out.graph=observe(after);for(const auto&st:stencils(base.first))if(intersects(ka,st.inputs)&&intersects(kb,st.inputs))out.contact.push_back(st.output);out.flags[3]=next.second.invalid();out.conflict=out.flags[3]?next.second:base.second;out.flags[0]=!out.contact.empty()||out.conflict.invalid();out.flags[1]=!out.flags[3]&&!records_equal(b,next.first);if(!next.second.invalid()&&!base.second.invalid()){const auto ea=isolated_events(pa,control_payload(following[0],cat)),eb=isolated_events(pb,control_payload(following[1],cat));out.merged=merge_events(ea,eb,base.first);out.merged_valid=true;out.flags[2]=events_repr(events)!=events_repr(out.merged);}return out;}
