Bytes conflict_wire(const Conflict&c){need(c.invalid(),"present conflict required");Bytes b;le(b,c.context?0:1,1);need(c.slots.size()<=2&&c.edges.size()<=2,"conflict intersection count");le(b,c.slots.size(),1);for(auto x:c.slots){le(b,x.first,4);le(b,x.second,1);}le(b,c.edges.size(),1);for(auto x:c.edges){le(b,x.first,4);le(b,x.second,1);}return b;}
struct RecordedStep {Q::State state;Q::Events events;std::array<Control,2>controls;Lift lift;StepObservation observation;Bytes R,O,LO,D,chain,tick;};
RecordedStep record_step(const Q::State&before,const Q::State&reference,const Lift&lift,const Lift&reference_lift,const std::array<Control,2>&controls,const Bytes&previous,const Catalogue&cat,unsigned offset,bool wrap,std::uint64_t*executed=nullptr){need(previous.size()==32&&offset>=1&&offset<=304,"observed record offset/chain");if(executed)++*executed;const auto result=Q::step(before);const std::array<Control,2>following={advance_control(controls[0],cat),advance_control(controls[1],cat)};const auto observation=observe_step(before,result.state,result.events,controls,following,cat);const auto next_lift=advance_lift(before,result.state,result.events,lift);if(wrap)no_wrap(result.state,next_lift);const auto R=raw(checkpoint(result.state)),O=raw(step_repr(observation)),LO=raw(lift_repr(result.state,next_lift,&reference,&reference_lift));const auto D=raw("("+events_repr(result.events)+", "+str(O)+", "+str(LO)+")");auto hash_input=previous;for(int i=7;i>=0;--i)hash_input.push_back(std::uint8_t(std::uint64_t(R.size())>>(8*i)));append(hash_input,R);append(hash_input,D);const auto chain=sha256(hash_input),events=Q::encode_events(result.events);unsigned flags=0;for(unsigned i=0;i<4;++i)flags|=unsigned(observation.flags[i])<<i;Bytes tick;le(tick,offset,2);append(tick,pack(result.state));append(tick,lift_wire(next_lift));le(tick,events.size(),2);append(tick,events);append(tick,chain);le(tick,flags,1);need(tick.size()<=222,"Tick bound");return {result.state,result.events,following,next_lift,observation,R,O,LO,D,chain,tick};}
Control component_control(const Q::State&s,const Component&c,const Catalogue&cat){const auto v=view(s);need(c.plus==1&&c.minus==1&&c.F+c.K==2&&c.e.size()<=2,"not a short Q2 component");const auto plus=*std::find_if(c.c.begin(),c.c.end(),[&](const auto&x){return x.slot==v.eta;});const auto minus=*std::find_if(c.c.begin(),c.c.end(),[&](const auto&x){return x.slot!=v.eta;});std::map<CK,int>edges;for(auto e:c.e)edges[{e.owner,e.axis}]=e.q*(v.eta?-1:1);std::set<CK>used;auto current=plus.site;Record r;auto internal=[&](unsigned direction){unsigned axis=0;while(AX[v.origin/8][axis]!=(direction-1)/2)++axis;return 2*axis+(direction-1)%2;};while(current!=minus.site){std::vector<std::pair<unsigned,std::uint32_t>>ports;for(unsigned d=0;d<6;++d){const auto owner=d%2?shift(v.L,current,d/2,-1):current;auto it=edges.find({owner,d/2});if(it!=edges.end()&&it->second*(d%2?-1:1)==1)ports.emplace_back(d,owner);}need(ports.size()==1&&r.path.size()<2,"component lacks unique Q2 path");const auto d=ports[0].first;used.insert({ports[0].second,d/2});r.path.push_back(internal(d+1));current=shift(v.L,current,d/2,d%2?-1:1);}need(used.size()==edges.size(),"component extra edge");r.velocity={internal(plus.direction),internal(minus.direction)};r.credit={plus.credit,minus.credit};r.attempt={plus.attempted,minus.attempted};const auto code=background(v,plus.site);unsigned color=0;for(unsigned a=0;a<3;++a)color|=((code>>a)&1)<<(2-a);auto it=cat.index.find(record_row(r));need(it!=cat.index.end(),"Q2 relative record index");Control out{v.L,v.origin,v.eta,v.tick,xyz(v.L,plus.site),(phase(v.tick)*8+color)*6192+it->second};check_control(out);return out;}
std::vector<Point> control_support(const Control&c,const Catalogue&cat){const auto v=control_payload(c,cat);std::set<Point>owned{c.plus};Point position=c.plus;for(auto d:cat.records.at(c.node%6192).path){const auto vector=physical(c,dir(d)),target=add(position,vector);owned.insert(std::find(vector.begin(),vector.end(),1)!=vector.end()?position:target);position=target;}owned.insert(position);std::set<Point>centers;for(auto p:owned)for(int i=-1;i<=1;++i)for(int j=-1;j<=1;++j)for(int k=-1;k<=1;++k)centers.insert(add(p,{i,j,k}));std::map<std::uint32_t,std::vector<Point>>by_site;for(auto p:centers)by_site[site(c.L,p)].push_back(p);auto support=owned;support.insert(centers.begin(),centers.end());for(const auto&st:stencils(v)){const auto output=xyz(c.L,st.output.site);for(const auto&key:st.inputs){const auto point=xyz(c.L,key.site);Point delta{};for(unsigned a=0;a<3;++a){delta[a]=mod(point[a]-output[a]+1,c.L)-1;need(std::abs(delta[a])<=1,"stencil exceeds radius one");}for(auto center:by_site.at(st.output.site))support.insert(add(center,delta));}}need(support.size()<=375,"support template bound");return {support.begin(),support.end()};}
std::string points_repr(const std::vector<Point>&p){std::vector<std::string>s;for(auto x:p)s.push_back(pt(x));return tup(s);}
std::int64_t floor_div(std::int64_t x,std::int64_t d){need(d!=0,"zero interval denominator");auto q=x/d;const auto r=x%d;if(r&&((r<0)!=(d<0)))--q;return q;}
struct Interval{bool hit=false,upper=false;std::int64_t lo=0,hi=0;};
Interval interval(const Point&w,const Point&slope){Interval out{true,false,0,0};for(unsigned a=0;a<3;++a){const auto x=w[a],d=slope[a];if(!d){if(std::abs(x)>2)return {};continue;}const auto lo=d>0?-floor_div(2+x,d):-floor_div(2-x,-d);const auto hi=d>0?floor_div(2-x,d):floor_div(-2-x,d);out.lo=std::max(out.lo,lo);out.hi=out.upper?std::min(out.hi,hi):hi;out.upper=true;if(out.hi<out.lo)return {};}return out;}
