bool translated(const Q::State&a,const Lift&la,const Q::State&b,const Lift&lb,Point&d){const auto va=view(a),vb=view(b);if(va.L!=vb.L||va.origin!=vb.origin||va.eta!=vb.eta)return false;Point sa{},sb{};for(auto p:la.c)for(unsigned j=0;j<3;++j)sa[j]+=p[j];for(auto p:lb.c)for(unsigned j=0;j<3;++j)sb[j]+=p[j];d=sub(sb,sa);for(auto&x:d){if(x%4)return false;x/=4;if(x%2)return false;}using CR=std::tuple<Point,unsigned,unsigned,unsigned,unsigned>;using ER=std::tuple<Point,unsigned,int>;std::vector<CR>ac,bc;std::vector<ER>ae,be;for(unsigned i=0;i<4;++i){const auto x=va.c[i],y=vb.c[i];ac.emplace_back(add(la.c[i],d),x.slot,x.direction,x.credit,x.attempted);bc.emplace_back(lb.c[i],y.slot,y.direction,y.credit,y.attempted);}for(unsigned i=0;i<va.e.size();++i)ae.emplace_back(add(la.e[i],d),va.e[i].axis,va.e[i].q);for(unsigned i=0;i<vb.e.size();++i)be.emplace_back(lb.e[i],vb.e[i].axis,vb.e[i].q);std::sort(ac.begin(),ac.end());std::sort(bc.begin(),bc.end());std::sort(ae.begin(),ae.end());std::sort(be.begin(),be.end());return ac==bc&&ae==be;}
struct Capture{std::vector<std::string>witnesses;Bytes bits=Bytes(287,0);};
Capture capture(const std::vector<Q::State>&history,const std::vector<Lift>&lifts,std::uint64_t*executed=nullptr){need(!history.empty()&&history.size()==lifts.size()&&history.size()<=305,"capture history shape");std::vector<std::int64_t>diameters;std::vector<bool>joined;for(unsigned i=0;i<history.size();++i){validate_lift(history[i],lifts[i]);if(i){if(executed)++*executed;const auto expected=Q::step(history[i-1]);need(Q::encode_state(expected.state)==Q::encode_state(history[i])&&advance_lift(history[i-1],history[i],expected.events,lifts[i-1])==lifts[i],"capture history is not complete law trajectory");}const auto d=span(lifts[i]);diameters.push_back(*std::max_element(d.begin(),d.end()));bool j=false;for(const auto&c:observe(history[i]).components)j=j||c.c.size()==4;joined.push_back(j);}Capture out;unsigned bit=0;for(unsigned end=1;end<=304;++end)for(unsigned start=0;start<end;++start)if((end-start)%19==0){if(end<history.size()){const auto maxd=*std::max_element(diameters.begin()+start,diameters.begin()+end+1);const bool join=std::any_of(joined.begin()+start,joined.begin()+end+1,[](bool x){return x;});Point d{};if(maxd<=8&&join&&translated(history[start],lifts[start],history[end],lifts[end],d)){out.bits[bit/8]|=std::uint8_t(1U<<(bit%8));std::vector<std::string>offsets;for(unsigned i=start;i<=end;++i)if(joined[i])offsets.push_back(std::to_string(i-start));out.witnesses.push_back("CaptureWitness(start="+std::to_string(start)+", end="+std::to_string(end)+", ordinal_start="+decimal(Q::microtick_hex(history[start]))+", ordinal_end="+decimal(Q::microtick_hex(history[end]))+", period="+std::to_string(end-start)+", translation="+pt(d)+", translating="+boolean(d!=Point{})+", maximum_diameter="+std::to_string(maxd)+", joined_offsets="+tup(offsets)+")");}}++bit;}need(bit==2296,"capture pair count");return out;}
