    explicit JsonParser(const std::string&s,bool build_numbers=false):s_(s),build_numbers_(build_numbers){}
    Json parse(){auto j=value(0);need(p_==s_.size()&&json_dump(j)==s_,"noncanonical JSON");return j;}
