struct Begin {unsigned group=0,representative=0,multiplicity=0,orbit=0;std::array<std::uint8_t,10>preparation{};Q::State state;Lift lift;std::array<Control,2>controls;std::array<std::uint32_t,2>seeds{};unsigned lift_steps=0;Bytes bytes;};
Begin decode_begin(const Bytes&b){need(b.size()<=333,"BEGIN size");Reader r{b};const auto group=r.u(4),representative=r.u(4),multiplicity=r.u(4),orbit=r.u(4);std::array<std::uint8_t,10>pid{};for(auto&x:pid)x=std::uint8_t(r.u(1));const auto n=r.u(4);need(n>=193&&n<=194,"campaign initial state wire length");const auto wire=r.take(std::size_t(n));const auto state=Q::decode_state(wire.data(),wire.size());const auto lift=read_lift(r,state);std::array<Control,2>controls={read_control(r,state),read_control(r,state)};std::array<std::uint32_t,2>seeds={std::uint32_t(r.u(4)),std::uint32_t(r.u(4))};const auto steps=r.u(1);const auto hash=r.take(32);r.end();need(hash==sha256(raw(checkpoint(state))),"BEGIN Python checkpoint hash");need(Q::payload(state).L==64&&Q::microtick_hex(state)==hx(steps)&&steps>=1&&steps<=19,"BEGIN context/ordinal");need(lift==initial_lift(state),"BEGIN canonical initial lift");no_wrap(state,lift);need(multiplicity>0,"BEGIN multiplicity");return {unsigned(group),unsigned(representative),unsigned(multiplicity),unsigned(orbit),pid,state,lift,controls,seeds,unsigned(steps),b};}
