void qualify_build_manifest(const Json&b){
    need(b.at("schema").text()=="strict-composite-native-build-1"&&b.at("status").text()=="PASS_BUILD"&&b.at("exit_code").natural()==0,"qualified production build receipt required");
    const auto&paths=b.at("tool_paths");const auto&versions=b.at("tool_version");
    paths.keys({"as","cc1plus","collect2","driver","ld"});versions.keys({"as","cc1plus","collect2","driver","ld"});
    std::map<std::string,Json>tools_by_path;
    for(const auto&kv:paths.object){const auto path=absolute_path(kv.second.text());const auto&v=versions.at(kv.first);v.keys({"exit_code","stdout","stderr"});need(v.at("exit_code").natural()==0,"tool version query failed");(void)v.at("stdout").text();(void)v.at("stderr").text();need(tools_by_path.emplace(path,b.at("tool_sha256").at(path)).second,"distinct tool roles required");}
    same_json(Json::mapping(tools_by_path),b.at("tool_sha256"),"complete five-tool inventory");
    same_json(b.at("tool_sha256"),b.at("pre_tool_sha256"),"build pre-tool drift");same_json(b.at("tool_sha256"),b.at("post_tool_sha256"),"build post-tool drift");
    need(absolute_path(paths.at("driver").text())==absolute_path(b.at("compiler").text())&&b.at("compiler_sha256").text()==b.at("tool_sha256").at(paths.at("driver").text()).text(),"compiler driver identity");
    const auto&command=b.at("command");need(command.kind==Json::Array&&!command.array.empty(),"complete build command required");need(absolute_path(command.array.front().text())==absolute_path(paths.at("driver").text()),"build command driver");std::set<std::string>arguments;for(const auto&v:command.array)arguments.insert(v.text());need(arguments.count("-v")&&arguments.count("-H"),"verbose tool and include provenance required");
    std::map<std::string,Json>originals,copies,runtimes;
    for(const auto&kv:b.at("source_sha256").object)need(originals.emplace(std::filesystem::path(kv.first).filename().string(),kv.second).second,"duplicate source basename");
    for(const auto&kv:b.at("snapshot_sha256").object)need(copies.emplace(std::filesystem::path(kv.first).filename().string(),kv.second).second,"duplicate snapshot basename");
    Json::mapping(originals).keys({"sparse_q4_kernel_v1.hpp","sparse_q4_kernel_v1.cpp","composite_interaction_adapter_v1.cpp"});same_json(Json::mapping(originals),Json::mapping(copies),"build snapshots differ from originals");same_json(b.at("source_sha256"),b.at("post_source_sha256"),"build source drift");
    for(const auto&kv:b.at("compiler_runtime_sha256").object){need(runtimes.emplace(std::filesystem::path(kv.first).filename().string(),kv.second).second,"duplicate compiler runtime basename");}Json::mapping(runtimes).keys({"libgcc_s_seh-1.dll","libstdc++-6.dll","libwinpthread-1.dll"});
    const auto directory=std::filesystem::path(absolute_path(b.at("binary").text())).parent_path();
    const auto stderr_bytes=file((directory/"stderr").string(),16U<<20);need(hex(sha256(stderr_bytes))==b.at("stderr_sha256").text(),"owned build stderr hash");need(hex(file_sha256((directory/"stdout").string()))==b.at("stdout_sha256").text(),"build stdout hash");
    std::istringstream lines(str(stderr_bytes));std::string line;std::set<std::string>listed_headers,declared_headers;
    while(std::getline(lines,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();std::size_t prefix=0;while(prefix<line.size()&&line[prefix]=='.')++prefix;if(prefix&&prefix<line.size()&&line[prefix]==' ')listed_headers.insert(absolute_path(line.substr(prefix+1)));}
    for(const auto&kv:b.at("include_sha256").object){declared_headers.insert(absolute_path(kv.first));}need(!listed_headers.empty()&&listed_headers==declared_headers,"complete retained include inventory");
    for(const auto key:{"source_sha256","snapshot_sha256","tool_sha256","include_sha256","compiler_runtime_sha256"})verify_pins(b.at(key));
}
